#include <print>
#include <queue>
#include <string>

int main() {
    std::queue<std::string> line;
    line.push("小明");
    line.push("小红");
    line.push("小强");
    std::println("排头: {}", line.front());
    std::println("排尾: {}", line.back());
    std::queue<int> hall;
    for (int i = 1; i <= 5; ++i) {
        hall.push(i);
        std::println("{} 号进门，厅内 {} 人", i, hall.size());
        if (i % 2 == 0) {
            std::println("窗口办理 {} 号", hall.front());
            hall.pop();
        }
    }
    while (!line.empty()) {
        std::println("叫号: {}", line.front());
        line.pop();
    }
    return 0;
}

